import deob.client;
import sign.signlink;
import jagex2.io.*;
import jagex2.graphics.*;
import jagex2.config.Component;
import java.io.*;
import java.net.*;
import java.nio.file.*;
import java.util.*;
public class LastLoginOracle {
 static client c=new client();static DataOutputStream out;static int cases,opened;static final int[] seed={225,140,650,655};static int[] ids=new int[6],roots=new int[2];static Component[] probes=new Component[6];static int[] colours=new int[6];
 static Jagfile jag(String dir,String name)throws Exception{return new Jagfile(Files.readAllBytes(Paths.get(dir,name)),false);}
 static void text(DataOutputStream f,String text)throws Exception{if(text==null){f.writeInt(-1);return;}byte[] bytes=text.getBytes("US-ASCII");f.writeInt(bytes.length);f.write(bytes);}
 static byte[] payload(int address,int days,int recovery,int unread)throws Exception{ByteArrayOutputStream b=new ByteArrayOutputStream();DataOutputStream d=new DataOutputStream(b);d.writeInt(address);d.writeShort(days);d.writeByte(recovery);d.writeShort(unread);return b.toByteArray();}
 static void read(byte[] payload)throws Exception{byte[] bytes=new byte[10];bytes[0]=(byte)140;System.arraycopy(payload,0,bytes,1,9);final ByteArrayInputStream input=new ByteArrayInputStream(bytes);Socket socket=new Socket(){public void setSoTimeout(int n){}public void setTcpNoDelay(boolean b){}public InputStream getInputStream(){return input;}public OutputStream getOutputStream(){return new ByteArrayOutputStream();}};c.stream=new ClientStream(c,(byte)2,socket);c.packetType=-1;c.randomIn=null;c.ingame=true;if(!c.read(false)||!c.ingame||input.available()!=0||c.packetType!=-1)throw new Exception("read140");}
 static void layout(int mode,int target){if(mode==1){for(Component v:Component.instances)if(v!=null && v.clientCode==target)v.clientCode=0;}if(mode==2){int found=0;for(Component v:Component.instances)if(v!=null && found<2){v.clientCode=target;v.layer=1234+found++;}}}
 static void one(int address,int days,int recovery,int unread,int viewport,int mode)throws Exception{
  byte[] p=payload(address,days,recovery,unread);out.write(p);out.writeInt(viewport);int sidebar=cases%2==0?-1:55,chat=cases%3==0?-1:27;out.writeInt(sidebar);out.writeInt(chat);out.writeInt(mode);String prior=cases%17==0?null:cases%11==0?"unknown":cases%13==0?String.join("",Collections.nCopies(255,"h")):"prior.example";text(out,prior);
  c.viewportInterfaceId=viewport;c.sidebarInterfaceId=sidebar;c.chatInterfaceId=chat;c.reportAbuseInterfaceID=77;c.reportAbuseInput="Report kept";c.reportAbuseMuteOption=true;c.chatbackInputOpen=true;c.chatbackInput="42";c.showSocialInput=true;c.socialInput="social kept";c.chatTyped="ordinary kept";c.pressedContinueOption=true;c.redrawSidebar=c.redrawChatback=c.redrawSideicons=false;signlink.dns=prior;signlink.dnsreq="127.0.0.9";c.out.pos=0;
  int[] codes=new int[Component.instances.length],layers=codes.clone();for(int i=0;i<codes.length;i++)if(Component.instances[i]!=null){codes[i]=Component.instances[i].clientCode;layers[i]=Component.instances[i].layer;}
  layout(mode,recovery==201?650:655);read(p);if(c.out.pos>0)opened++;
  for(int value:new int[]{c.lastAddress,c.daysSinceLastLogin,c.daysSinceRecoveriesChanged,c.unreadMessages,c.viewportInterfaceId,c.sidebarInterfaceId,c.chatInterfaceId,c.reportAbuseInterfaceID})out.writeInt(value);text(out,c.reportAbuseInput);out.writeBoolean(c.reportAbuseMuteOption);out.writeBoolean(c.chatbackInputOpen);text(out,c.chatbackInput);out.writeBoolean(c.showSocialInput);text(out,c.socialInput);text(out,c.chatTyped);text(out,signlink.dns);text(out,signlink.dnsreq);out.writeBoolean(c.pressedContinueOption);out.writeBoolean(c.redrawSidebar);out.writeBoolean(c.redrawChatback);out.writeBoolean(c.redrawSideicons);
  out.writeInt(c.out.pos);out.write(c.out.data,0,c.out.pos);Isaac cipher=c.out.random;for(int value:new int[]{cipher.count,cipher.a,cipher.b,cipher.c})out.writeInt(value);for(int value:cipher.rsl)out.writeInt(value);for(int value:cipher.mem)out.writeInt(value);
  for(int i=0;i<codes.length;i++)if(Component.instances[i]!=null){Component.instances[i].clientCode=codes[i];Component.instances[i].layer=layers[i];}
  for(int i=0;i<6;i++){Component v=probes[i];v.text="old text";v.colour=0x102030+i;c.updateInterfaceContent(0,v);text(out,v.text);out.writeInt(v.colour);}cases++;
 }
 public static void main(String[] args)throws Exception{
  Jagfile title=jag(args[0],"title"),media=jag(args[0],"media"),interfaces=jag(args[0],"interface");PixFont[] fonts={new PixFont(title,"p11",530),new PixFont(title,"p12",530),new PixFont(title,"b12",530),new PixFont(title,"q8",530)};Component.unpack(media,fonts,1,interfaces);Arrays.fill(ids,-1);for(Component v:Component.instances)if(v!=null && v.clientCode>=650 && v.clientCode<=655 && ids[v.clientCode-650]<0)ids[v.clientCode-650]=v.id;System.out.println("Available last-login widgets="+Arrays.toString(ids));for(int i=0;i<6;i++){probes[i]=ids[i]>=0?Component.instances[ids[i]]:new Component();probes[i].clientCode=650+i;colours[i]=probes[i].colour;}roots[0]=Component.instances[ids[0]].layer;roots[1]=Component.instances[ids[5]].layer;System.out.println("Cached last-login widgets="+Arrays.toString(ids)+" roots="+Arrays.toString(roots));signlink.active=false;signlink.reporterror=false;c.out=new Packet(5,new byte[5000]);c.out.random=new Isaac((byte)1,seed);ByteArrayOutputStream body=new ByteArrayOutputStream();out=new DataOutputStream(new BufferedOutputStream(body));
  for(int address:new int[]{0,1,0x7f000001,0x80ff0102,0xffffffff,0xc0000201})for(int days:new int[]{0,1,2,65535})for(int recovery:new int[]{0,1,2,199,200,201,202,255})for(int unread:new int[]{0,1,2,65535})for(int viewport:new int[]{-1,0,42})one(address,days,recovery,unread,viewport,0);
  Random random=new Random(225140);for(int i=0;i<96;i++)one(random.nextInt(),random.nextInt(65536),random.nextInt(256),random.nextInt(65536),i%3==0?-1:42,0);for(int mode=0;mode<3;mode++)for(int recovery:new int[]{200,201})one(0xc0000201,1,recovery,1,-1,mode);
  out.flush();try(DataOutputStream f=new DataOutputStream(new BufferedOutputStream(new FileOutputStream(args[1])))){f.writeInt(0x4c4c3235);f.writeInt(cases);for(int v:seed)f.writeInt(v);for(int id:ids)f.writeInt(id);for(int root:roots)f.writeInt(root);f.write(body.toByteArray());}System.out.println("Original last-login:"+cases+" read140 states,"+opened+" close231 observations;full cipher/interfaces/report/input/DNS and6 content text/colour states;4 redraw/continue metadata fields captured separately");
  for(int i=0;i<6;i++)probes[i].colour=colours[i];
  try(DataOutputStream f=new DataOutputStream(new BufferedOutputStream(new FileOutputStream(args[2])))){f.writeInt(0x4c553235);f.writeInt(24);for(int root:roots)f.writeInt(root);for(int i=0;i<24;i++){c.lastAddress=i%7==0?0:0xc0000201;c.daysSinceLastLogin=new int[]{0,1,2,65535}[i%4];c.daysSinceRecoveriesChanged=new int[]{0,1,2,199,200,201}[i%6];c.unreadMessages=new int[]{0,1,2,65535}[i%4];signlink.dns=i%3==0?"unknown":i%3==1?"192.0.2.1":"resolved.example";int root=roots[i%2];for(int v:new int[]{c.lastAddress,c.daysSinceLastLogin,c.daysSinceRecoveriesChanged,c.unreadMessages,root})f.writeInt(v);text(f,signlink.dns);int[] pixels=new int[512*334];Pix2D.bind(512,pixels,-657,334);c.drawInterface(0,0,38682,Component.instances[root],0);for(int pixel:pixels)f.writeInt(pixel);}}System.out.println("Original last-login UI:24 complete512x334 panels/4104192 pixels;cached roots andcompleted/numeric/unknown DNS");
 }
}
